     1	import type { Item } from "./policy.js";
     2	
     3	/**
     4	 * Matching a damage entry to the insured item it hit.
     5	 *
     6	 * This is its own decision, separate from what a damage settles at: it
     7	 * answers "which covered item was this?", not "what does the MHPCO pay?".
     8	 * The two change for different reasons and on different schedules -- the
     9	 * deductible is a figure the MHPCO revises, whereas matching is a question
    10	 * about the policy's contents, and the spec already has it moving twice more
    11	 * on its own: an incident may name the same type twice and must then consume
    12	 * two distinct insured items, and an entry naming a type the policy does not
    13	 * cover must be turned away rather than settled.
    14	 */
    15	
    16	/**
    17	 * A damage entry naming a type the policy does not cover stands in as a bare
    18	 * item for now, so that it settles under the no-clause fallback. This is the
    19	 * placeholder the rejection rule will replace: once "damaged item not part of
    20	 * the policy" is active, no such entry reaches settlement at all, and the
    21	 * fallback disappears with it rather than being carried along.
    22	 */
    23	function notCoveredByThisPolicy(itemType: string): Item {
    24	  return { type: itemType };
    25	}
    26	
    27	/** The insured item a damage of this type hit. */
    28	export function damagedItem(items: readonly Item[], itemType: string): Item {
    29	  return (
    30	    items.find((item) => item.type === itemType) ??
    31	    notCoveredByThisPolicy(itemType)
    32	  );
    33	}
