     1	import type { Item } from "./policy.js";
     2	import { enchantmentLevelOf } from "./policy.js";
     3	
     4	/**
     5	 * The special clauses that decide what share of a damage the MHPCO
     6	 * reimburses. Which clauses exist, what each grants, and which one wins when
     7	 * several apply is a policy table the MHPCO revises on its own schedule --
     8	 * independently of the deductible, of how a damage entry is matched to an
     9	 * insured item, and of the cap. It is kept here so that revising a clause
    10	 * means editing this list and nothing else.
    11	 *
    12	 * The share is stated before the deductible: a clause reduces what counts as
    13	 * reimbursable damage, and the deductible is taken off whatever remains.
    14	 */
    15	
    16	/** Damage to a highly enchanted item is reimbursed at half its amount. */
    17	const HIGH_ENCHANTMENT_REIMBURSEMENT_RATE = 0.5;
    18	const HIGH_ENCHANTMENT_CLAIM_LEVEL = 8;
    19	
    20	/**
    21	 * An item that qualifies for no special clause at all is reimbursed in full;
    22	 * the deductible is the only thing the policyholder bears. This is the
    23	 * absence of a clause rather than a clause of its own -- a distinction that
    24	 * matters, because a clause that grants full reimbursement in its own right
    25	 * can still be overridden by a stronger one, whereas this fallback is
    26	 * whatever is left when nothing applies.
    27	 *
    28	 * The spec's dragon-material clause ("damage to items made of dragon
    29	 * material is fully reimbursed") has deliberately not been written as a
    30	 * clause of its own, because under the present clause set it cannot change
    31	 * any payout. It would grant rate 1, which is what the fallback already
    32	 * grants, and where it competes with the high-enchantment clause the spec
    33	 * has the 50 % rule win -- so dragon material and no clause at all settle
    34	 * identically for every item, at every enchantment level. All three of the
    35	 * spec's dragon examples (enchantment 5 -> 700, 8 -> 400, 9 -> 400) are
    36	 * satisfied here without reading `material` at all.
    37	 *
    38	 * This stops being true the moment a clause is added that grants less than
    39	 * full reimbursement and that dragon material should override. At that
    40	 * point dragon material becomes observable and earns its own entry.
    41	 */
    42	const NO_CLAUSE_REIMBURSEMENT_RATE = 1;
    43	
    44	/**
    45	 * The claim office's own enchantment threshold, deliberately not shared with
    46	 * the premium side's. Both read the same item property, but they answer
    47	 * different questions -- what a risk costs to insure against, versus what it
    48	 * settles at -- and the spec fixes them at different levels and lets them
    49	 * move apart. An item at enchantment 6 carries the premium surcharge and
    50	 * still gets reimbursed in full.
    51	 */
    52	function qualifiesForHighEnchantmentClause(item: Item): boolean {
    53	  return enchantmentLevelOf(item) >= HIGH_ENCHANTMENT_CLAIM_LEVEL;
    54	}
    55	
    56	/** What share of a damage the MHPCO reimburses, before the deductible. */
    57	export function reimbursementRateOf(item: Item): number {
    58	  return qualifiesForHighEnchantmentClause(item)
    59	    ? HIGH_ENCHANTMENT_REIMBURSEMENT_RATE
    60	    : NO_CLAUSE_REIMBURSEMENT_RATE;
    61	}
