     1	import type { Item } from "./policy.js";
     2	import { enchantmentLevelOf } from "./policy.js";
     3	
     4	/** A cursed item adds a risk surcharge on its own base premium. */
     5	const CURSE_SURCHARGE_RATE = 0.5;
     6	
     7	/** Highly enchanted items add a risk surcharge on their own base premium. */
     8	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
     9	const HIGH_ENCHANTMENT_LEVEL = 5;
    10	
    11	function isCursed(item: Item): boolean {
    12	  return item.cursed === true;
    13	}
    14	
    15	function carriesHighEnchantmentSurcharge(item: Item): boolean {
    16	  return enchantmentLevelOf(item) >= HIGH_ENCHANTMENT_LEVEL;
    17	}
    18	
    19	function riskSurchargeRateOf(item: Item): number {
    20	  const curseRate = isCursed(item) ? CURSE_SURCHARGE_RATE : 0;
    21	  const enchantmentRate = carriesHighEnchantmentSurcharge(item)
    22	    ? HIGH_ENCHANTMENT_SURCHARGE_RATE
    23	    : 0;
    24	  return curseRate + enchantmentRate;
    25	}
    26	
    27	/**
    28	 * Item-specific risk surcharges apply to the base premium of the affected
    29	 * item, not to the policy base premium.
    30	 */
    31	export function riskSurchargeOf(item: Item, itemBasePremium: number): number {
    32	  return itemBasePremium * riskSurchargeRateOf(item);
    33	}
