     1	import {
     2	  COMPONENT_INSURANCE_VALUE,
     3	  componentsBasePremium,
     4	  isComponent,
     5	} from "./component-price-rules.js";
     6	import { priceMainItems } from "./main-item.js";
     7	import type { Item } from "./policy.js";
     8	import type { ItemPricing } from "./premium-contribution.js";
     9	import { combinedPricing } from "./premium-contribution.js";
    10	import { insuranceValueOf as mainItemInsuranceValueOf } from "./price-list.js";
    11	
    12	/**
    13	 * The MHPCO insures two kinds of thing, and each kind is governed by its own
    14	 * price rules: main items follow the price list, components may form blocks.
    15	 * Both of a kind's figures -- what insuring it costs and what it is insured
    16	 * for -- come from those same rules, as the spec states them together.
    17	 *
    18	 * This module is the one place that decides which rules govern an item, so
    19	 * that a new kind of insurable thing is added here and nowhere else.
    20	 */
    21	
    22	/**
    23	 * Components are insured at a flat rate and carry no item-specific risk:
    24	 * a rune has neither an enchantment level nor a material to be cursed.
    25	 */
    26	function priceComponents(components: readonly Item[]): ItemPricing {
    27	  return {
    28	    basePremium: componentsBasePremium(components),
    29	    riskSurcharges: 0,
    30	  };
    31	}
    32	
    33	/**
    34	 * Pricing is decided per kind rather than per item, because a kind's rules
    35	 * may look at the whole group: three alike components form a block only
    36	 * when they are priced together.
    37	 */
    38	export function priceItems(items: readonly Item[]): ItemPricing {
    39	  return combinedPricing(
    40	    priceMainItems(items.filter((item) => !isComponent(item))),
    41	    priceComponents(items.filter(isComponent)),
    42	  );
    43	}
    44	
    45	/** What the rules governing this item's kind state it is insured for. */
    46	export function insuranceValueOf(item: Item): number {
    47	  return isComponent(item)
    48	    ? COMPONENT_INSURANCE_VALUE
    49	    : mainItemInsuranceValueOf(item);
    50	}
===== component-price-rules.ts =====
     1	import type { Item } from "./policy.js";
     2	
     3	/**
     4	 * The price rules governing components such as runes and moonstones: what
     5	 * each is insured for, and what insuring them costs -- including the
     6	 * building block, the one concession that makes components cheaper than
     7	 * their number alone would suggest.
     8	 */
     9	
    10	/** Components such as runes and moonstones share one base premium. */
    11	const COMPONENT_BASE_PREMIUM = 25;
    12	
    13	const COMPONENT_TYPES: readonly string[] = ["rune", "moonstone"];
    14	
    15	/**
    16	 * Each component is insured for its own value. The building block is a
    17	 * premium concession only: it never reduces what a component is insured for.
    18	 */
    19	export const COMPONENT_INSURANCE_VALUE = 250;
    20	
    21	/** A building block of alike components is offered at a special premium. */
    22	const COMPONENT_BLOCK_SIZE = 3;
    23	const COMPONENT_BLOCK_BASE_PREMIUM = 60;
    24	
    25	export function isComponent(item: Item): boolean {
    26	  return COMPONENT_TYPES.includes(item.type);
    27	}
    28	
    29	/** Components count as "alike" -- and so may form a block -- per item type. */
    30	function alikeGroupSizes(components: readonly Item[]): readonly number[] {
    31	  const sizes = new Map<string, number>();
    32	  for (const component of components) {
    33	    sizes.set(component.type, (sizes.get(component.type) ?? 0) + 1);
    34	  }
    35	  return [...sizes.values()];
    36	}
    37	
    38	/**
    39	 * A block requires *exactly* the block size: 4 or 7 alike components are
    40	 * priced per component, not as blocks plus a remainder.
    41	 */
    42	function alikeGroupBasePremium(groupSize: number): number {
    43	  if (groupSize === COMPONENT_BLOCK_SIZE) {
    44	    return COMPONENT_BLOCK_BASE_PREMIUM;
    45	  }
    46	  return groupSize * COMPONENT_BASE_PREMIUM;
    47	}
    48	
    49	export function componentsBasePremium(components: readonly Item[]): number {
    50	  return alikeGroupSizes(components).reduce(
    51	    (sum, groupSize) => sum + alikeGroupBasePremium(groupSize),
    52	    0,
    53	  );
    54	}
===== premium-contribution.ts =====
     1	/**
     2	 * What insured items contribute to a premium, before policy-wide modifiers.
     3	 *
     4	 * The two contributions are kept apart all the way up because policy-wide
     5	 * modifiers scale only the policy base premium: a risk surcharge has already
     6	 * been assessed against its own item and must not be scaled again.
     7	 */
     8	export interface ItemPricing {
     9	  /** Sum of item base premiums -- the policy base premium. */
    10	  readonly basePremium: number;
    11	  /** Item-specific risk surcharges, each on its own item's base premium. */
    12	  readonly riskSurcharges: number;
    13	}
    14	
    15	/** An item that contributes nothing -- the identity for combining pricings. */
    16	export const NO_PRICING: ItemPricing = { basePremium: 0, riskSurcharges: 0 };
    17	
    18	/**
    19	 * Pricings combine by adding each contribution separately: base premiums
    20	 * accumulate into the policy base premium, and risk surcharges accumulate
    21	 * alongside it, because policy-wide modifiers scale only the former.
    22	 */
    23	export function combinedPricing(
    24	  left: ItemPricing,
    25	  right: ItemPricing,
    26	): ItemPricing {
    27	  return {
    28	    basePremium: left.basePremium + right.basePremium,
    29	    riskSurcharges: left.riskSurcharges + right.riskSurcharges,
    30	  };
    31	}
    32	
    33	/** What a whole group of priced items contributes, combined. */
    34	export function combinedPricings(
    35	  pricings: readonly ItemPricing[],
    36	): ItemPricing {
    37	  return pricings.reduce(combinedPricing, NO_PRICING);
    38	}
===== price-list.ts =====
     1	import type { Item } from "./policy.js";
     2	
     3	/**
     4	 * The MHPCO price list states one row per main item type: what the item is
     5	 * insured for, and what insuring it costs. The spec states the two figures
     6	 * together ("Sword: 1000 G insurance value, 100 G base premium"), and the
     7	 * MHPCO revises them together, so they are kept in one row rather than in
     8	 * parallel tables that would have to be kept in step by hand.
     9	 *
    10	 * The list covers main items only. Components (runes, moonstones) are
    11	 * priced elsewhere, by the rules that let them form blocks, so a component
    12	 * type has no row here and this list declines to state its figures.
    13	 */
    14	interface PriceListRow {
    15	  /** Unstated while no active example has yet fixed this row's figure. */
    16	  readonly insuranceValue?: number;
    17	  readonly basePremium?: number;
    18	}
    19	
    20	const MAIN_ITEM_PRICE_LIST: Readonly<Record<string, PriceListRow>> = {
    21	  sword: { insuranceValue: 1000, basePremium: 100 },
    22	  amulet: { insuranceValue: 600, basePremium: 60 },
    23	  staff: { basePremium: 80 },
    24	  potion: { basePremium: 40 },
    25	};
    26	
    27	/**
    28	 * A figure this list does not state -- because the type has no row, or
    29	 * because the row is silent on that figure -- costs and covers nothing.
    30	 */
    31	const UNSTATED = 0;
    32	
    33	function priceListRowOf(item: Item): PriceListRow {
    34	  return MAIN_ITEM_PRICE_LIST[item.type] ?? {};
    35	}
    36	
    37	/** What the MHPCO charges to insure one main item of this type, before modifiers. */
    38	export function basePremiumOf(item: Item): number {
    39	  return priceListRowOf(item).basePremium ?? UNSTATED;
    40	}
    41	
    42	/** What the MHPCO's main item price list states this type is insured for. */
    43	export function insuranceValueOf(item: Item): number {
    44	  return priceListRowOf(item).insuranceValue ?? UNSTATED;
    45	}
===== policy-modifier.ts =====
     1	import type { Customer } from "./policy.js";
     2	
     3	/**
     4	 * Policy-wide modifiers scale the policy base premium (the sum of all item
     5	 * base premiums). Item-specific modifiers live with the items they affect.
     6	 *
     7	 * Three independent policies live here, and they answer to different facts:
     8	 * the initial assessment surcharge is a property of the quote itself, the
     9	 * loyalty discount is a property of the customer's relationship with the
    10	 * MHPCO, and the follow-up contract discount is a property of the
    11	 * customer's contract history in this scenario.
    12	 *
    13	 * Each is expressed as a signed adjustment to the policy base premium, so
    14	 * that a surcharge and a discount differ only in sign and the quote can sum
    15	 * them without knowing which is which.
    16	 */
    17	
    18	/** Long-standing customers are rewarded with a loyalty discount. */
    19	const LOYALTY_DISCOUNT_RATE = 0.2;
    20	const LOYALTY_YEARS = 2;
    21	
    22	const INITIAL_ASSESSMENT_SURCHARGE_RATE = 0.1;
    23	
    24	/** Every contract after the customer's first is discounted. */
    25	const FOLLOW_UP_CONTRACT_DISCOUNT_RATE = 0.15;
    26	
    27	/** What the quote is assessed against, beyond the items themselves. */
    28	export interface Contract {
    29	  readonly customer: Customer;
    30	  /** Contracts this customer already holds in the scenario. */
    31	  readonly previousContracts: number;
    32	}
    33	
    34	function isLongStanding(customer: Customer): boolean {
    35	  return customer.yearsWithMHPCO >= LOYALTY_YEARS;
    36	}
    37	
    38	/** A follow-up contract is any contract after the customer's first. */
    39	function isFollowUpContract(contract: Contract): boolean {
    40	  return contract.previousContracts > 0;
    41	}
    42	
    43	/** Long-standing customers are rewarded off the premium. */
    44	function loyaltyDiscount(contract: Contract, policyBasePremium: number): number {
    45	  return isLongStanding(contract.customer)
    46	    ? -policyBasePremium * LOYALTY_DISCOUNT_RATE
    47	    : 0;
    48	}
    49	
    50	function followUpContractDiscount(
    51	  contract: Contract,
    52	  policyBasePremium: number,
    53	): number {
    54	  return isFollowUpContract(contract)
    55	    ? -policyBasePremium * FOLLOW_UP_CONTRACT_DISCOUNT_RATE
    56	    : 0;
    57	}
    58	
    59	/**
    60	 * Every item in a quote is assessed as a first insurance, regardless of
    61	 * customer history, so this surcharge always applies.
    62	 */
    63	function initialAssessmentSurcharge(policyBasePremium: number): number {
    64	  return policyBasePremium * INITIAL_ASSESSMENT_SURCHARGE_RATE;
    65	}
    66	
    67	/**
    68	 * The net signed adjustment the policy-wide modifiers make to the policy
    69	 * base premium: positive for a surcharge, negative for a discount.
    70	 */
    71	export function policyWideAdjustment(
    72	  contract: Contract,
    73	  policyBasePremium: number,
    74	): number {
    75	  return (
    76	    initialAssessmentSurcharge(policyBasePremium) +
    77	    loyaltyDiscount(contract, policyBasePremium) +
    78	    followUpContractDiscount(contract, policyBasePremium)
    79	  );
    80	}

